package io.github.chronicle.core.server;

import io.github.chronicle.core.ChronicleCore;
import io.github.chronicle.core.campaign.SessionPhase;
import io.github.chronicle.core.menu.CoreMenuModel.Fact;
import io.github.chronicle.core.offering.OfferingDefinition;
import io.github.chronicle.core.offering.temporary.*;
import io.github.chronicle.core.play.EventSource;
import io.github.chronicle.core.stats.OfferingAttributes;
import net.fabricmc.fabric.api.entity.event.v1.ServerPlayerEvents;
import net.fabricmc.fabric.api.event.lifecycle.v1.ServerLifecycleEvents;
import net.fabricmc.fabric.api.event.lifecycle.v1.ServerTickEvents;
import net.fabricmc.fabric.api.networking.v1.ServerPlayConnectionEvents;
import net.minecraft.entity.attribute.*;
import net.minecraft.entity.attribute.EntityAttributes;
import net.minecraft.registry.entry.RegistryEntry;
import net.minecraft.server.MinecraftServer;
import net.minecraft.server.network.ServerPlayerEntity;
import net.minecraft.util.Identifier;
import net.minecraft.util.WorldSavePath;

import java.io.IOException;
import java.util.*;

/** Generic durable temporary sacrifices. Campaign handlers own external prices and benefits. */
public final class TemporaryOfferings {
    public static final String OWNER="chronicle_core:temporary_offerings";
    private static final String MODIFIER_PREFIX="temporary_offerings/";
    private static final Map<String,Definition> DEFINITIONS=new TreeMap<>();
    private static final Map<MinecraftServer,State> SERVERS=new IdentityHashMap<>();
    private static boolean registered,frozen;
    private TemporaryOfferings(){}
    public record Station(String identity,Map<String,String> context){public Station{if(identity==null||identity.isBlank()||identity.length()>512||context==null||context.size()>16)throw new IllegalArgumentException("invalid temporary offering station");TreeMap<String,String> copy=new TreeMap<>();for(var entry:context.entrySet()){if(entry.getKey()==null||!entry.getKey().matches("[a-z][a-z0-9_.-]{0,63}")||entry.getValue()==null||entry.getValue().length()>512)throw new IllegalArgumentException("invalid temporary station context");copy.put(entry.getKey(),entry.getValue());}context=Map.copyOf(copy);}}
    public record Prepared(long revision,TemporaryOfferingTerms terms){public Prepared{if(revision<0||terms==null)throw new IllegalArgumentException("invalid temporary offering preview");}}
    public interface Handler {
        TemporaryOfferingTerms preview(ServerPlayerEntity player,Station station);
        /** Called exactly once after the durable CLAIMED record. Any failure leaves GM-reviewed uncertainty. */
        void commit(ServerPlayerEntity player,Station station,TemporaryOfferingClaim claim)throws Exception;
    }
    public record Definition(String id,Handler handler){public Definition{OfferingDefinition.validId(id);Objects.requireNonNull(handler);}}
    public static synchronized void registerDefinition(Definition definition){if(frozen||DEFINITIONS.size()>=32||DEFINITIONS.putIfAbsent(definition.id(),definition)!=null)throw new IllegalStateException("temporary offering definitions are frozen, full or duplicated");}
    public static synchronized void register(){
        if(registered)return;registered=true;OfferingAttributes.initialize();
        EventSources.registerAuthority("temporaryoffer:",TemporaryOfferings::verifySource,true);
        ServerLifecycleEvents.SERVER_STARTING.register(server->frozen=true);ServerLifecycleEvents.SERVER_STARTED.register(TemporaryOfferings::start);
        ServerLifecycleEvents.SERVER_STOPPED.register(server->{State state=SERVERS.remove(server);if(state!=null&&state.store!=null)try{state.store.close();}catch(IOException error){ChronicleCore.LOGGER.error("Could not release temporary offering lock",error);}RuntimeHolds.release(server,OWNER);});
        ServerPlayConnectionEvents.JOIN.register((handler,sender,server)->reconcileSafely(handler.player));
        ServerPlayerEvents.AFTER_RESPAWN.register((oldPlayer,player,alive)->{State state=SERVERS.get(player.getEntityWorld().getServer());if(state==null||state.ledger==null||state.failure!=null)copyOwned(oldPlayer,player);else try{assertAuthority(oldPlayer,state.ledger);reconcile(player,state.ledger);}catch(Exception error){fail(player.getEntityWorld().getServer(),state,error);copyOwned(oldPlayer,player);}});
        ServerTickEvents.END_SERVER_TICK.register(TemporaryOfferings::tick);
        GameSetupTools.register(new GameSetupTools.Tool(OWNER,"Temporary offerings","Duration-limited sacrifices and their exact recovery evidence. Recovery records a reviewed decision only after manual correction; it never replays, refunds or manufactures an outcome.",
                List.of(new GameSetupTools.Verb("prepare_review","Pin oldest uncertain claim",GameSetupTools.Guard.OPERATOR,false),new GameSetupTools.Verb("confirm_review","Confirm pinned manual review",GameSetupTools.Guard.OPERATOR,true),new GameSetupTools.Verb("refresh","Refresh",GameSetupTools.Guard.READ_ONLY,false)),TemporaryOfferings::status,TemporaryOfferings::tool));
    }
    public static Definition definition(String id){Definition result=DEFINITIONS.get(id);if(result==null)throw new IllegalArgumentException("unknown temporary offering: "+id);return result;}
    public static Prepared preview(ServerPlayerEntity player,String source,Definition definition,Station station){
        State state=ready(player.getEntityWorld().getServer());ensureCapacity(state,player.getUuid());if(state.ledger.closedSources().contains(source))throw new IllegalStateException("temporary offering source ended");
        if(state.ledger.unresolved().stream().anyMatch(claim->claim.player().equals(player.getUuid())||claim.station().equals(station.identity())))throw new IllegalStateException("a temporary offering awaits GM review");
        return new Prepared(state.ledger.revision(),definition.handler().preview(player,station));
    }
    public static TemporaryOfferingClaim purchase(ServerPlayerEntity player,String source,Definition definition,Station station,UUID transaction,Prepared expected)throws Exception{
        MinecraftServer server=player.getEntityWorld().getServer();State state=ready(server);var prior=claim(state,transaction);
        if(prior.isPresent()){var claim=prior.get();if(!claim.player().equals(player.getUuid())||!claim.source().equals(source)||!claim.offering().equals(definition.id())||!claim.station().equals(station.identity()))throw new IllegalStateException("temporary transaction belongs to another offering");return claim;}
        Prepared current=preview(player,source,definition,station);if(!current.equals(expected))throw new IllegalStateException("temporary offering terms or costs changed; reopen the Altar");long clock=PlayRuntime.elapsedTicks(server);
        TemporaryOfferingClaim claim=new TemporaryOfferingClaim(transaction,player.getUuid(),source,definition.id(),station.identity(),clock,Math.addExact(clock,current.terms().durationTicks()),current.terms(),TemporaryOfferingClaim.State.CLAIMED,null);
        String authority="temporaryoffer:"+transaction;String sourceReceipt=EventSources.prepare(player,EventSources.id(authority,"chronicle_core:prayer_completed",definition.id(),""),new EventSource("chronicle_core:prayer_completed",definition.id(),""),authority);
        try{publish(state,state.ledger.add(expected.revision(),claim));}
        catch(Exception error){try{EventSources.cancelAuthority(server,authority);}catch(Exception suppressed){error.addSuppressed(suppressed);}throw error;}
        try{definition.handler().commit(player,station,claim);publish(state,state.ledger.transition(state.ledger.revision(),transaction,TemporaryOfferingClaim.State.CLAIMED,TemporaryOfferingClaim.State.COMPLETE,null));reconcile(player,state.ledger);EventSources.complete(server,sourceReceipt,true);return state.ledger.claim(transaction).orElseThrow();}
        catch(Exception error){failUncertain(server,state,claim,error);throw error;}
    }
    public static TemporaryOfferingLedger ledger(MinecraftServer server){return ready(server).ledger;}
    public static List<TemporaryOfferingClaim> active(MinecraftServer server,String source){State state=ready(server);long clock=PlayRuntime.elapsedTicks(server);return state.ledger.claims().stream().filter(claim->claim.source().equals(source)&&claim.active(clock)).toList();}
    public static void closeSource(MinecraftServer server,String source)throws IOException{State state=ready(server);try{publish(state,state.ledger.close(source));for(var player:server.getPlayerManager().getPlayerList())reconcile(player,state.ledger);refreshHold(server,state);}catch(IOException|RuntimeException error){fail(server,state,error);throw error;}}
    public static boolean sourceDefinitelyAbsent(MinecraftServer server,UUID operation){State state=ready(server);try{state.store.verifyUnchanged();return state.ledger.claim(operation).isEmpty()&&state.store.archived(operation).isEmpty();}catch(IOException error){throw new IllegalStateException("temporary offering absence cannot be proved",error);}}
    public static boolean sourceCommitted(MinecraftServer server,UUID operation,UUID player,String offering){State state=ready(server);var claim=claim(state,operation).orElse(null);return claim!=null&&claim.player().equals(player)&&claim.offering().equals(offering)&&switch(claim.state()){case COMPLETE,EXPIRED,CLOSED->true;default->false;};}
    public static int maintain(MinecraftServer server)throws IOException{State state=ready(server);TemporaryOfferingLedger next=state.store.archiveTerminals(state.ledger,ignored->true);int count=state.ledger.claims().size()-next.claims().size();state.ledger=next;return count;}
    private static void start(MinecraftServer server){State state=new State();SERVERS.put(server,state);try{state.store=new TemporaryOfferingStore(server.getSavePath(WorldSavePath.ROOT).resolve("chronicle/temporary-offerings.json"));state.ledger=state.store.loadOrCreate();refreshHold(server,state);ChronicleCore.LOGGER.info("Temporary offering authority ready: {} claims, {} unresolved",state.ledger.claims().size(),state.ledger.unresolved().size());}catch(Exception error){fail(server,state,error);}}
    private static void tick(MinecraftServer server){State state=SERVERS.get(server);if(state==null||state.failure!=null||state.ledger==null)return;try{if(server.getTicks()%200==0)state.store.verifyUnchanged();TemporaryOfferingLedger next=state.ledger.expire(PlayRuntime.elapsedTicks(server));if(next!=state.ledger)publish(state,next);if(server.getTicks()%20==0){if(server.getPlayerManager().getPlayerList().size()>256)throw new IllegalStateException("more than256 online players");for(var player:server.getPlayerManager().getPlayerList())reconcile(player,state.ledger);}}catch(Exception error){fail(server,state,error);}}
    private static void publish(State state,TemporaryOfferingLedger next)throws IOException{if(next==state.ledger)return;state.ledger=state.store.save(next,state.ledger);}
    private static Optional<TemporaryOfferingClaim> claim(State state,UUID operation){Optional<TemporaryOfferingClaim> live=state.ledger.claim(operation);if(live.isPresent())return live;try{return state.store.archived(operation);}catch(IOException error){throw new IllegalStateException("archived temporary offering evidence is unavailable",error);}}
    private static void ensureCapacity(State state,UUID player){long playerClaims=state.ledger.claims().stream().filter(claim->claim.player().equals(player)).count();if(playerClaims<32&&state.ledger.claims().size()<1024)return;try{state.ledger=state.store.archiveTerminals(state.ledger,claim->playerClaims>=32&&claim.player().equals(player)||state.ledger.claims().size()>=1024);}catch(IOException error){throw new IllegalStateException("terminal temporary offering history could not be archived",error);}}
    private static boolean verifySource(MinecraftServer server,io.github.chronicle.core.progression.SourceLedger.Receipt receipt){UUID operation=UUID.fromString(receipt.authority().substring("temporaryoffer:".length()));State state=ready(server);TemporaryOfferingClaim claim=claim(state,operation).orElse(null);if(claim==null){if(sourceDefinitelyAbsent(server,operation))EventSources.cancelAuthority(server,receipt.authority());return false;}if(!claim.player().equals(receipt.actor())||!claim.offering().equals(receipt.target()))return false;if(claim.state()==TemporaryOfferingClaim.State.REVIEWED){EventSources.cancelAuthority(server,receipt.authority());return false;}return switch(claim.state()){case COMPLETE,EXPIRED,CLOSED->true;default->false;};}
    private static State required(MinecraftServer server){if(!server.isOnThread())throw new IllegalStateException("temporary offerings require the server thread");State state=SERVERS.get(server);if(state==null)throw new IllegalStateException("temporary offering authority has not started");return state;}
    private static State ready(MinecraftServer server){State state=required(server);if(state.failure!=null||state.ledger==null)throw new IllegalStateException("temporary offering authority unavailable; inspect its GM recovery status");return state;}
    private static void failUncertain(MinecraftServer server,State state,TemporaryOfferingClaim claim,Exception error){ChronicleCore.LOGGER.error("Temporary offering {} is durably claimed but its external result is uncertain; GM review is required",claim.transaction(),error);refreshHold(server,state);}
    private static void fail(MinecraftServer server,State state,Exception error){if(state.failure==null)ChronicleCore.LOGGER.error("Temporary offering authority held; existing evidence and modifiers retained",error);state.failure="Temporary offering data unavailable; inspect world/chronicle/temporary-offerings.json.";RuntimeHolds.hold(server,OWNER,state.failure);}
    private static void refreshHold(MinecraftServer server,State state){if(state.failure!=null){RuntimeHolds.hold(server,OWNER,state.failure);return;}if(!state.ledger.unresolved().isEmpty())RuntimeHolds.hold(server,OWNER,"A temporary Altar offering has an uncertain external result; an operator must manually inspect and review it.");else RuntimeHolds.release(server,OWNER);}
    private static Identifier modifierId(UUID transaction){return Identifier.of("chronicle_core",MODIFIER_PREFIX+transaction);}
    private static UUID transactionOf(Identifier id){if(!id.getNamespace().equals("chronicle_core")||!id.getPath().startsWith(MODIFIER_PREFIX))return null;try{return UUID.fromString(id.getPath().substring(MODIFIER_PREFIX.length()));}catch(IllegalArgumentException error){throw new IllegalStateException("unrecognized temporary offering modifier",error);}}
    private static EntityAttributeInstance instance(ServerPlayerEntity player,RegistryEntry<EntityAttribute> type){EntityAttributeInstance value=player.getAttributeInstance(type);if(value==null)throw new IllegalStateException("missing temporary offering player attribute");return value;}
    private static Map<Identifier,EntityAttributeModifier> desired(TemporaryOfferingLedger ledger,UUID player,long clock,boolean health){TreeMap<Identifier,EntityAttributeModifier> result=new TreeMap<>();for(var claim:ledger.claims()){if(!claim.player().equals(player)||!claim.active(clock))continue;double value=health?claim.terms().health():claim.terms().exhaustionPercent()/100.0;if(value!=0){Identifier id=modifierId(claim.transaction());result.put(id,new EntityAttributeModifier(id,value,EntityAttributeModifier.Operation.ADD_VALUE));}}return result;}
    private static void project(EntityAttributeInstance attribute,Map<Identifier,EntityAttributeModifier> wanted){for(var modifier:List.copyOf(attribute.getModifiers()))if(transactionOf(modifier.id())!=null&&!wanted.containsKey(modifier.id()))attribute.removeModifier(modifier.id());for(var modifier:wanted.values())if(!modifier.equals(attribute.getModifier(modifier.id()))||!attribute.getPersistentModifiers().contains(modifier))attribute.overwritePersistentModifier(modifier);}
    private static void assertAuthority(ServerPlayerEntity player,TemporaryOfferingLedger ledger){Set<UUID> known=new HashSet<>();ledger.claims().stream().filter(claim->claim.player().equals(player.getUuid())).forEach(claim->known.add(claim.transaction()));for(var type:List.of(EntityAttributes.MAX_HEALTH,OfferingAttributes.EXHAUSTION_MULTIPLIER))for(var modifier:instance(player,type).getModifiers()){UUID transaction=transactionOf(modifier.id());if(transaction!=null&&!known.contains(transaction))throw new IllegalStateException("temporary offering modifier has no durable claim");}}
    private static void reconcile(ServerPlayerEntity player,TemporaryOfferingLedger ledger){assertAuthority(player,ledger);long clock=PlayRuntime.elapsedTicks(player.getEntityWorld().getServer());project(instance(player,EntityAttributes.MAX_HEALTH),desired(ledger,player.getUuid(),clock,true));project(instance(player,OfferingAttributes.EXHAUSTION_MULTIPLIER),desired(ledger,player.getUuid(),clock,false));if(player.getHealth()>player.getMaxHealth())player.setHealth(player.getMaxHealth());}
    private static void reconcileSafely(ServerPlayerEntity player){State state=SERVERS.get(player.getEntityWorld().getServer());if(state==null||state.ledger==null||state.failure!=null)return;try{state.store.verifyUnchanged();reconcile(player,state.ledger);}catch(Exception error){fail(player.getEntityWorld().getServer(),state,error);}}
    private static void copyOwned(ServerPlayerEntity oldPlayer,ServerPlayerEntity player){for(var type:List.of(EntityAttributes.MAX_HEALTH,OfferingAttributes.EXHAUSTION_MULTIPLIER))for(var modifier:instance(oldPlayer,type).getPersistentModifiers())if(transactionOf(modifier.id())!=null)instance(player,type).overwritePersistentModifier(modifier);if(player.getHealth()>player.getMaxHealth())player.setHealth(player.getMaxHealth());}
    private static GameSetupTools.Status status(net.minecraft.server.command.ServerCommandSource source){State state=required(source.getServer());List<Fact> facts=new ArrayList<>();facts.add(new Fact("Status",state.failure==null?(state.ledger.unresolved().isEmpty()?"Ready":"BLOCKED: uncertain external result requires exact GM review"):state.failure));facts.add(new Fact("Authority","world/chronicle/temporary-offerings.json; no automatic retry, refund or backup promotion."));
        var oldest=state.ledger==null?null:state.ledger.unresolved().stream().findFirst().orElse(null);if(oldest!=null){facts.add(new Fact("Uncertain operation",oldest.transaction().toString()));facts.add(new Fact("Claim digest",oldest.digest()));facts.add(new Fact("Current state",oldest.state().name()));facts.add(new Fact("Claim",oldest.offering()+" for "+oldest.player()+" at "+oldest.station()));facts.add(new Fact("Active clock",oldest.claimedAtTicks()+" -> "+oldest.expiresAtTicks()));facts.add(new Fact("Modifiers","health "+oldest.terms().health()+", exhaustion "+oldest.terms().exhaustionPercent()+"%; inspect evidence before manual correction."));}
        UUID actor=source.getPlayer()==null?null:source.getPlayer().getUuid();Recovery pin=actor==null?null:state.recovery.get(actor);if(pin!=null)facts.add(new Fact("Pinned review",pin.operation+" / "+pin.digest+" / "+pin.state));Map<String,String> disabled=new HashMap<>();String recovery=recoveryDenied(source,state,oldest);if(recovery!=null){disabled.put("prepare_review",recovery);disabled.put("confirm_review",recovery);}else if(pin==null)disabled.put("confirm_review","Pin and inspect the exact uncertain claim first.");return new GameSetupTools.Status((state.ledger==null?0:state.ledger.revision())+state.reviewRevision,facts,disabled);}
    private static String recoveryDenied(net.minecraft.server.command.ServerCommandSource source,State state,TemporaryOfferingClaim oldest){if(state.failure!=null)return state.failure;if(!source.hasPermissionLevel(2)||source.getPlayer()==null)return "Recovery requires an online operator.";if(ChronicleRuntime.service(source.getServer()).state().phase()==SessionPhase.ACTIVE)return "Recovery requires non-active play.";if(RuntimeHolds.heldByOthers(source.getServer(),Set.of(OWNER,EventSources.HOLD)))return "Resolve the unrelated operation hold first.";if(oldest==null)return "There is no uncertain temporary offering.";return null;}
    private static String tool(net.minecraft.server.command.ServerCommandSource source,String verb)throws Exception{State state=ready(source.getServer());var oldest=state.ledger.unresolved().stream().findFirst().orElse(null);String denied=recoveryDenied(source,state,oldest);if(verb.equals("refresh"))return "Temporary offering status refreshed.";if(denied!=null)throw new IllegalStateException(denied);UUID actor=source.getPlayerOrThrow().getUuid();if(verb.equals("prepare_review")){state.recovery.put(actor,new Recovery(oldest.transaction(),oldest.digest(),oldest.state()));state.reviewRevision++;return "Pinned exact operation "+oldest.transaction()+". Inspect its digest, state and external world/player evidence; manually correct it before confirmation.";}Recovery pin=state.recovery.get(actor);if(pin==null)throw new IllegalStateException("Pin the exact uncertain claim first.");TemporaryOfferingClaim current=state.ledger.claim(pin.operation).orElseThrow(()->new IllegalStateException("Pinned operation disappeared."));if(!current.digest().equals(pin.digest)||current.state()!=pin.state||current.state()!=TemporaryOfferingClaim.State.CLAIMED)throw new IllegalStateException("Pinned claim changed; prepare review again.");publish(state,state.ledger.transition(state.ledger.revision(),current.transaction(),TemporaryOfferingClaim.State.CLAIMED,TemporaryOfferingClaim.State.REVIEWED,source.getName()));state.recovery.remove(actor);state.reviewRevision++;EventSources.cancelAuthority(source.getServer(),"temporaryoffer:"+current.transaction());refreshHold(source.getServer(),state);return "Recorded manual review of exact operation "+current.transaction()+"; no cost or benefit was replayed, refunded or manufactured.";}
    private static final class State{TemporaryOfferingStore store;TemporaryOfferingLedger ledger;String failure;long reviewRevision;final Map<UUID,Recovery> recovery=new HashMap<>();}
    private record Recovery(UUID operation,String digest,TemporaryOfferingClaim.State state){}
}
